/* From Uiverse.io by SelfMadeSystem  - Tags: simple, animation, login, purple, form, card, sign-up */
.__UIV_SCOPE__ .form-container {
  position: relative;
  perspective: 50rem;
  width: 50rem;
  height: 50rem;
}

.__UIV_SCOPE__ #switch {
  display: none;
}

.__UIV_SCOPE__ .sign-up-form,
.__UIV_SCOPE__ .log-in-form {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.__UIV_SCOPE__ .sign-up-container,
.__UIV_SCOPE__ .log-in-container {
  position: absolute;
  display: flex;
  flex-direction: column;
  inset: 0;
  margin: auto;
  width: 20rem;
  height: 20rem;
  background: #2c164f;
  color: #fff;
  padding: 1rem;
  border-radius: 0.5rem;
}

.__UIV_SCOPE__ .switch-label {
  font-size: x-small;
  text-decoration: underline;
  cursor: pointer;
}

.__UIV_SCOPE__ .form-title {
  font-size: x-large;
  font-weight: bold;
}

.__UIV_SCOPE__ :where(.sign-up-form, .log-in-form) label {
  font-size: x-small;
  padding-top: 0.5rem;
  padding-left: 0.25rem;
}

.__UIV_SCOPE__ :where(.sign-up-form, .log-in-form) input {
  background-color: #fff2;
  box-sizing: border-box;
  color: white;
  border: 0;
  border-bottom: 2px solid #cfb2ff;
  padding: 0.25rem;
  border-top-left-radius: 0.25rem;
  border-top-right-radius: 0.25rem;
}

.__UIV_SCOPE__ :where(.sign-up-form, .log-in-form) input:focus-visible {
  outline: none;
  border: 1px solid white;
  border-bottom: 2px solid #cfb2ff;
}

.__UIV_SCOPE__ :where(.sign-up-form, .log-in-form) button {
  margin-top: auto;
  background-color: #ffffff4b;
  color: white;
  border: 0;
  padding: 0.25rem;
  border-radius: 0.25rem;
  cursor: pointer;
}

.__UIV_SCOPE__ .forgot-pwd {
  font-size: x-small;
  text-decoration: underline;
  margin-left: auto;
  cursor: pointer;
}

/* Social yoinked from uiverse.io/Yaya12085/short-panda-24 */

.__UIV_SCOPE__ .social-message {
  display: flex;
  align-items: center;
  padding-top: 1rem;
}

.__UIV_SCOPE__ .line {
  height: 1px;
  flex: 1 1 0%;
  background-color: #cfb2ff;
}

.__UIV_SCOPE__ .social-message .message {
  padding-left: 0.75rem;
  padding-right: 0.75rem;
  font-size: 0.875rem;
  line-height: 1.25rem;
  color: #fff;
}

.__UIV_SCOPE__ .social-icons {
  display: flex;
  justify-content: center;
}

.__UIV_SCOPE__ .social-icons .icon {
  border-radius: 0.125rem;
  padding: 0.75rem;
  padding-bottom: 0.25rem;
  border: none;
  background-color: transparent;
  margin-left: 8px;
  cursor: pointer;
}

.__UIV_SCOPE__ .social-icons .icon svg {
  height: 1.25rem;
  width: 1.25rem;
  fill: #fff;
}

.__UIV_SCOPE__ .sign-up-container {
  animation: hello 0.5s linear forwards;
}

.__UIV_SCOPE__ .log-in-container {
  animation: unhello 0.5s linear forwards;
}

.__UIV_SCOPE__ #switch:checked ~ .sign-up-container {
  animation: unhello 0.5s linear forwards;
}

.__UIV_SCOPE__ #switch:checked ~ .log-in-container {
  animation: hello 0.5s linear forwards;
}

@keyframes hello {
  0% {
    transform: rotateY(-90deg);
    display: none;
  }
  50% {
    transform: rotateY(-90deg);
    display: flex;
  }
  100% {
    transform: rotateY(0deg);
    display: flex;
  }
}

@keyframes unhello {
  0% {
    transform: rotateY(0deg);
    display: flex;
  }
  50% {
    transform: rotateY(90deg);
    display: flex;
  }
  100% {
    transform: rotateY(90deg);
    display: none;
  }
}
